import{_ as d,o as e,c as a,a5 as r}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"口语证据卡：从口音焦虑到可验证互动","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/speaking-evidence.zh.md","filePath":"public/downloads/worksheets/speaking-evidence.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/speaking-evidence.zh.md"};function i(l,t,n,b,o,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="口语证据卡-从口音焦虑到可验证互动" tabindex="-1">口语证据卡：从口音焦虑到可验证互动 <a class="header-anchor" href="#口语证据卡-从口音焦虑到可验证互动" aria-label="Permalink to &quot;口语证据卡：从口音焦虑到可验证互动&quot;">​</a></h1><p>把这张卡复制到私有笔记中，一次只记录一个真实场景。原始录音优先保持私密；录到他人声音、客户信息、家庭内容、医疗信息或未公开项目时，先取得必要同意，或改用虚构信息练习。</p><h2 id="_1-定义任务、听众与边界" tabindex="-1">1. 定义任务、听众与边界 <a class="header-anchor" href="#_1-定义任务、听众与边界" aria-label="Permalink to &quot;1. 定义任务、听众与边界&quot;">​</a></h2><h3 id="speaking-evidence-—-yyyy-mm-dd" tabindex="-1">Speaking Evidence — YYYY-MM-DD <a class="header-anchor" href="#speaking-evidence-—-yyyy-mm-dd" aria-label="Permalink to &quot;Speaking Evidence — YYYY-MM-DD&quot;">​</a></h3><p>真实场景：<br> 任务：说明 / 问答 / 修复 / 协作 / 迁移<br> 听众与关系：<br> 结束后对方需要知道或做什么：<br> 时间限制：<br> 允许提纲 / 重录 / 字幕 / 词典 / AI：<br> 录音与上传许可：<br> 必须保持私密的内容：</p><p>完成标准要写成听众结果，例如“能复述风险和下一步”，不要只写“说得流利”。</p><h2 id="_2-记录参考变体与技术条件" tabindex="-1">2. 记录参考变体与技术条件 <a class="header-anchor" href="#_2-记录参考变体与技术条件" aria-label="Permalink to &quot;2. 记录参考变体与技术条件&quot;">​</a></h2><p>当前参考变体或音频来源：<br> 选择理由：<br> 只需识别、不必强迫模仿的差异：<br> 本轮新增的其他英语变体：</p><p>设备 / 麦克风：<br> 网络 / 房间噪声：<br> 录音或通话平台：<br> 听众是否熟悉主题与我的口音：</p><p>设备、网络、听众熟悉度改变时，不要把分数差异全部解释成能力变化。</p><h2 id="_3-保存三种无稿基线" tabindex="-1">3. 保存三种无稿基线 <a class="header-anchor" href="#_3-保存三种无稿基线" aria-label="Permalink to &quot;3. 保存三种无稿基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>样本</th><th>条件</th><th>录音位置</th><th>首次断点</th><th>是否完成任务</th></tr></thead><tbody><tr><td>90-120 秒独白</td><td>无稿说明真实经历/问题</td><td></td><td></td><td></td></tr><tr><td>五轮问答</td><td>至少一个陌生追问</td><td></td><td></td><td></td></tr><tr><td>一次互动修复</td><td>请求重复、确认范围、重述或总结</td><td></td><td></td><td></td></tr></tbody></table><p>我想传达的一句话主旨：<br> 听众必须听见的两个细节：<br> 关键数字 / 时间 / 责任 / 条件：<br> 我最担心被误解的地方：</p><p>不要先剪掉停顿、降噪或让 AI 生成稿件。首版要显示支架撤掉后能完成什么。</p><h2 id="_4-保存听众实际听见的内容" tabindex="-1">4. 保存听众实际听见的内容 <a class="header-anchor" href="#_4-保存听众实际听见的内容" aria-label="Permalink to &quot;4. 保存听众实际听见的内容&quot;">​</a></h2><p>请听众先听录音，不看转写：</p><table tabindex="0"><thead><tr><th>听众/条件</th><th>复述的主旨</th><th>复述的细节</th><th>猜测/重听位置</th><th>下一步反应</th></tr></thead><tbody><tr><td>听众 A</td><td></td><td></td><td></td><td></td></tr><tr><td>听众 B 或新设备</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>口音显著但仍然理解的地方：<br> 真正造成意思丢失的地方：<br> 理解需要额外努力但未误解的地方：<br> 听众反馈中可能存在的熟悉度或偏见：</p><p>一次主观评价不是结论。优先保存对方听见了什么、需要做什么，而不是“像不像某种标准口音”。</p><h2 id="_5-建立高影响问题地图" tabindex="-1">5. 建立高影响问题地图 <a class="header-anchor" href="#_5-建立高影响问题地图" aria-label="Permalink to &quot;5. 建立高影响问题地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>片段/时间</th><th>听众可能听成</th><th>我的原意</th><th>类型</th><th>任务影响</th><th>本轮动作</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>音 / 词尾 / 重音 / 停顿 / 词块 / 语法 / 组织</td><td>意思改变 / 任务阻断 / 高频重复 / 理解费力 / 低影响差异</td><td></td></tr></tbody></table><p>每轮只选一到三个问题。若差异只表明参考变体、地区或个人声音不同，且没有提高理解成本，就记录而不必强行修掉。</p><h2 id="_6-从词块进入陌生追问" tabindex="-1">6. 从词块进入陌生追问 <a class="header-anchor" href="#_6-从词块进入陌生追问" aria-label="Permalink to &quot;6. 从词块进入陌生追问&quot;">​</a></h2><p>本轮五个可替换词块：<br> 1.<br> 2.<br> 3.<br> 4.<br> 5.</p><p>主题变式：<br> 立场变式：<br> 听众变式：<br> 陌生追问：<br> 无稿回答位置：</p><p>若只在背熟稿件里流畅，换条件后无法继续，就减少完整句背诵，增加关键词重构与追问。</p><h2 id="_7-记录互动修复" tabindex="-1">7. 记录互动修复 <a class="header-anchor" href="#_7-记录互动修复" aria-label="Permalink to &quot;7. 记录互动修复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>断点</th><th>我怎样发现</th><th>修复动作</th><th>对方回应</th><th>如何确认恢复共同理解</th></tr></thead><tbody><tr><td>没听清 / 范围不明 / 需要思考 / 表达失败 / 共识不稳</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>我主动请求重复或确认的句子：<br> 我换用的说法：<br> 我最后总结的共识：<br> 若修复失败，下一次只改什么：</p><p>修复不是扣分项。没有发现误解、或发现后无法恢复任务，才是需要训练的地方。</p><h2 id="_8-教师、听众与-ai-反馈记录" tabindex="-1">8. 教师、听众与 AI 反馈记录 <a class="header-anchor" href="#_8-教师、听众与-ai-反馈记录" aria-label="Permalink to &quot;8. 教师、听众与 AI 反馈记录&quot;">​</a></h2><p>反馈者 / 工具 / 模型版本与日期：<br> 它使用的是原始音频还是转写：<br> 语音识别转写错误：<br> 它判断为高影响的问题：<br> 它是否区分口音差异、理解错误、理解费力、语法、语域与风格：<br> 我怎样用词典音频、教师或真实听众复核：<br> 我采纳 / 拒绝什么，为什么：</p><p>语音识别分数会受麦克风、噪声、网络、模型和口音影响，只能作为线索。</p><h2 id="_9-做延迟保持与迁移" tabindex="-1">9. 做延迟保持与迁移 <a class="header-anchor" href="#_9-做延迟保持与迁移" aria-label="Permalink to &quot;9. 做延迟保持与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>撤掉什么</th><th>改变的条件</th><th>输出</th><th>听众结果</th></tr></thead><tbody><tr><td>第 1 天</td><td>不使用 AI 稿件</td><td>原场景</td><td>首版与重录</td><td></td></tr><tr><td>第 3-7 天</td><td>撤掉原稿与示范音频</td><td>新主题或新听众</td><td>90-120 秒 + 追问</td><td></td></tr><tr><td>第 14 天</td><td>撤掉最近反馈</td><td>新设备、口音或时间压力</td><td>协作/决策说明</td><td></td></tr><tr><td>第 30 天</td><td>关闭全部练习提示</td><td>真实会议、面试或对话</td><td>完整任务</td><td></td></tr></tbody></table><p>七天后仍然能调用的部分：<br> 换条件后再次失败的部分：<br> 听众是否更少猜测或重听：<br> 下一轮变量：</p><h2 id="_10-评分与去留" tabindex="-1">10. 评分与去留 <a class="header-anchor" href="#_10-评分与去留" aria-label="Permalink to &quot;10. 评分与去留&quot;">​</a></h2><p>每项 0-2：<code>0=未完成</code>，<code>1=依赖提示或不稳定</code>，<code>2=当前条件下完成</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">第 1 天</th><th style="text-align:right;">第 7 天</th><th style="text-align:right;">第 14 天</th><th>证据理由</th></tr></thead><tbody><tr><td>任务与主线完成</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>听众实际恢复关键信息</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>理解不需要持续猜测或重听</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能处理陌生追问</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能发现并修复互动断点</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>换听众、设备或主题后仍能完成</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>当前证据支持：继续同一问题 / 增加变式 / 转向另一问题 / 暂停<br> 最重要的依据：<br> 仍不能推出的结论：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/5-speaking" target="_blank" rel="noreferrer">口语篇：让意思清楚到达</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/3-listening" target="_blank" rel="noreferrer">听力篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/8-job-search-english" target="_blank" rel="noreferrer">求职英语篇</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/speaking-evidence" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',43)])])}const c=d(h,[["render",i]]);export{g as __pageData,c as default};
